  print client " client errors"
}
' access.log

practice.solution:
# employees.csv: id,name,dept,salary,start_date,email
awk -F, '
NR > 1 {n++; total += $4}
NR > 1 && $4 > max {max = $4; top = $2}
END {
  print "employees: " n
  print "total: " total
  printf "average: %.2f\n", total / n
  print "top: " top " (" max ")"
}
' employees.csv

