practice.solution:
# orders.csv: order_id,customer,product,qty,unit_price
awk --csv '
BEGIN {printf "%-24s %4s %10s\n", "product", "qty", "total"}
NR > 1 {
  line = $4 * $5
  sum += line
  printf "%-24s %4d %10.2f\n", $3, $4, line
}
END {printf "%-24s %4s %10.2f\n", "TOTAL", "", sum}
' orders.csv
